//! Raw bindings to PETSc, generated by bindgen from `wrapper.h` against the installation in
//! `PETSC_DIR`. Safe wrappers live in the `petsc` crate.
//!
//! PETSc's vector type is called `Vec`: do not glob import this crate.

#![allow(
    non_upper_case_globals,
    non_camel_case_types,
    non_snake_case,
    dead_code,
    improper_ctypes,
    unsafe_op_in_unsafe_fn,
    clippy::all
)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));
